code3='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    outline = next(v for row in grid for v in row if v != bg)
    out = [row[:] for row in grid]
    for top in range(h - 2):
        for bottom in range(top + 2, h):
            for left in range(w - 2):
                for right in range(left + 2, w):
                    # The top must be explicitly drawn. A bottom clipped at the grid edge
                    # is accepted only when the preceding row continues the outline outward.
                    if not all(grid[top][c] == outline for c in range(left, right + 1)):
                        continue
                    bottom_drawn = all(grid[bottom][c] == outline for c in range(left, right + 1))
                    bottom_clipped = bottom == h - 1 and (
                        (left > 0 and any(grid[h-2][c] == outline for c in range(left))) or
                        (right < w-1 and any(grid[h-2][c] == outline for c in range(right+1,w)))
                    )
                    if not (bottom_drawn or bottom_clipped):
                        continue
                    if not all(grid[r][left] == outline and grid[r][right] == outline for r in range(top, bottom + 1)):
                        continue
                    area = (bottom - top - 1) * (right - left - 1)
                    if area == 1 and bottom == h - 1 and not bottom_drawn:
                        continue
                    for r in range(top + 1, bottom):
                        for c in range(left + 1, right):
                            if grid[r][c] == bg:
                                out[r][c] = 4
                    # A clipped lower edge includes the boundary row's interior.
                    if bottom == h-1 and bottom_clipped:
                        for c in range(left+1,right):
                            if grid[bottom][c] == bg: out[bottom][c] = 4
    return out
'''
